import math

def token_loss(correct_token_probability):
    if not 0 < correct_token_probability <= 1:
        raise ValueError("Probability must be in (0, 1]")
    return -math.log(correct_token_probability)

print(token_loss(0.8))
print(token_loss(0.1))

import numpy as np

def softmax_temperature(logits, temperature=1.0):
    if temperature <= 0:
        raise ValueError("Temperature must be positive")
    logits = np.asarray(logits, dtype=float) / temperature
    logits -= logits.max()
    exp_values = np.exp(logits)
    return exp_values / exp_values.sum()

logits = [2.0, 1.0, 0.1]
for temperature in [0.5, 1.0, 2.0]:
    print(temperature, softmax_temperature(logits, temperature))
